from pathlib import Path
p=Path(__file__).parent
icons={'back':'<path d="m14 5-7 7 7 7"/>','down':'<path d="m5 9 7 7 7-7"/>','up':'<path d="M12 20V4m-7 7 7-7 7 7"/>','plus':'<path d="M12 5v14M5 12h14"/>','radio':'<rect x="3" y="8" width="18" height="12" rx="1"/><path d="m4 8 14-5M6 12h5m-5 4h5"/><circle cx="16" cy="14" r="3"/>','terminal':'<rect x="3" y="4" width="18" height="16" rx="1"/><path d="m6 9 3 3-3 3m6 0h5"/>','mic':'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M6 11v1a6 6 0 0 0 12 0v-1m-6 7v3m-3 0h6"/>','attach':'<path d="m9 15 7-7a2 2 0 0 0-3-3l-8 8a4 4 0 0 0 6 6l9-9"/>','help':'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v.1"/>','more':'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'}
def icon(name): return '<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[name]+'</svg>'
def btn(label,name=None,cls=''): return f'<button type="button" class="control {cls}"'+(f' aria-label="{label}"' if name else '')+'>'+ (icon(name) if name else label)+'</button>'
def title(): return '<div class="lights" aria-label="Window controls">'+''.join(f'<button type="button" aria-label="{x}">{y}</button>' for x,y in [('Close','×'),('Minimize','−'),('Zoom','+')] )+'</div><strong class="project">cookbook-app</strong><span class="branch">⑂ phase3/generate-recipe</span><span class="host">on mac-mini-1</span>'+btn('Specialists')+'<div class="usage"><span>week</span><span class="meter" role="meter" aria-label="Weekly usage" aria-valuenow="26" aria-valuemin="0" aria-valuemax="100"><i></i></span><span>5d 11h</span></div>'+btn('Collapse title bar','down')
def toolbar(v):
    low=btn('Notes')+btn('Tasks')+btn('Radio','radio')+btn('Terminal','terminal')
    if v=='B': low='<div class="overflow">'+btn('More tools','more')+'<div class="menu" aria-label="More tools, open">'+btn('Notes')+btn('Tasks')+'<button class="control">'+icon('radio')+'Radio</button><button class="control">'+icon('terminal')+'Terminal</button></div></div>'
    return btn('Back','back')+'<button class="control specialist"><span class="count">20</span> Architect</button><button class="control autopilot" role="switch" aria-checked="true">Autopilot <span class="switch"><i></i></span></button><span class="toolbar-space"></span>'+btn('+ New')+low+btn('/commit')+btn('Help','help')
body='''<div class="transcript"><div class="col"><div class="turn you"><p class="bubble">Check the recipe flow before we merge.</p></div><div class="turn msg"><div class="prose"><p>The route and form agree on the new recipe schema. I’m checking the empty state and the save path next.</p><ul><li>Keep validation close to the input.</li><li>Preserve the draft when a request fails.</li></ul></div></div><div class="turn subagent-note"><span class="ring"></span><span>Architect · reviewing the recipe flow</span></div></div></div>
<div class="dock col"><section class="tools" aria-label="Live tools"><p class="tools-head"><span>Tools</span><span class="count">2 done · 1 running</span></p><ul><li class="tool"><span class="i i-check" aria-label="Done" role="img"></span><span class="tool-name">Read</span><span class="tool-arg">src/recipes/create.ts</span><span class="tool-time">0.1s</span></li><li class="tool"><span class="i i-check" aria-label="Done" role="img"></span><span class="tool-name">Read</span><span class="tool-arg">src/recipes/create.test.ts</span><span class="tool-time">0.2s</span></li><li class="tool is-live"><span class="live" aria-label="Running" role="img"></span><span class="tool-name">Bash</span><span class="tool-arg">pnpm test recipes</span><span class="tool-time">6s</span></li></ul></section>
<div class="activity"><span class="spinner" aria-label="Working" role="img"></span><span>Checking progress…</span><span class="elapsed">10m 49s · 1.3k tok</span><span class="toolbar-space"></span>COLLAPSE<button type="button" class="control stop">Stop</button></div><div class="composer"><div class="field">ATTACH<p class="input" role="textbox" aria-readonly="true" aria-label="Message"><span class="mention">@help</span> what should I check before I merge?</p><button type="button" class="control">Enhance</button>MIC<button type="button" class="send" aria-label="Send">SEND</button></div></div></div>
<footer class="status"><button type="button" class="control background-task">⚙ 1 background task</button><span class="toolbar-space"></span><button type="button" class="control">Context 19%</button><button type="button" class="control">Thinking medium</button><button type="button" class="control">Kleio <span>Claude Opus 5.5</span></button><button type="button" class="control"><span class="mention">@help</span> <span>Claude Opus 5.5</span></button></footer>'''
for a,b in [('COLLAPSE',btn('Collapse activity','down')),('ATTACH',btn('Attach','attach')),('MIC',btn('Microphone','mic')),('SEND',icon('up'))]: body=body.replace(a,b)
windows=[]
for v,caption in [('A','Selected baseline · everything visible, quieted.'),('B','Comparison only · low-use tools in an open overflow menu.'),('C','Comparison only · toolbar merged into the title bar.')]:
    chrome=f'<header class="chrome"><div class="title-row">{title()}</div><nav class="toolbar" aria-label="Code tools">{toolbar(v)}</nav></header>'
    windows.append(f'<section aria-labelledby="caption-{v}"><h2 id="caption-{v}" class="caption"><b>{v}</b> {caption}</h2><div class="kleio-code variant-{v}">{chrome}{body}</div></section>')
(p/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kleio · Window chrome</title><link rel="stylesheet" href="../code-transcript/final.css"><link rel="stylesheet" href="chrome.css"></head><body><main><header class="page-head"><span>KLEIO / CODE</span><h1>Less chrome. Same command.</h1><p>Variant A is locked as the selected window-chrome baseline. Composer alternatives have not been explored.</p></header>'+''.join(windows)+'</main></body></html>')
